import json
schedule=[('cobalt',[0,1,2,3,4],1320,360),('reed',[0,2,4],1380,180),('plum',[1,3,5],30,150),('shell',[6],1350,90),('gold',[0],0,90),('elm',[5],60,180)]
def receiver(d,m,fault=None):
    covered=[]
    for i,(r,days,s,e) in enumerate(schedule):
        if s<e:
            yes=d in days and s<=m<e
        elif fault=='day_owner':
            yes=d in days and (m>=s or m<e)
        else:
            yes=(d in days and m>=s) or ((d-1)%7 in days and m<e)
        if yes: covered.append(((e-s)%1440,i,r))
    if not covered: return 'idle'
    return (min(covered,key=lambda x:x[1]) if fault=='first_match' else min(covered))[2]
jobs=[(1,29),(1,30),(1,150),(1,179),(1,180),(5,59),(5,60),(5,149),(5,150),(5,180),(6,1349),(6,1350),(0,0),(0,89),(0,90),(2,359),(2,360),(4,1380)]
witnesses={}
for fault,other in [('day_owner','first_match'),('first_match','day_owner')]:
    for d in range(7):
        for m in range(1440):
            expected=receiver(d,m)
            if receiver(d,m,fault)!=expected and receiver(d,m,other)==expected:
                witnesses[fault]={'job':{'receiver':{'day':d,'minute':m}},'expected':expected}
                break
        if fault in witnesses: break
assert len(witnesses)==2
for fault,w in witnesses.items():
    q=w['job']['receiver']; d=q['day']; m=q['minute']
    assert 0<=d<=6 and 0<=m<=1439
    assert receiver(d,m)==w['expected'] and receiver(d,m,fault)!=w['expected']
    other='first_match' if fault=='day_owner' else 'day_owner'
    assert receiver(d,m,other)==w['expected']
print(json.dumps({'routes':[receiver(d,m) for d,m in jobs],'witnesses':witnesses},separators=(',',':')))

